sketches.source:
setcpm(88/4)

// The Sun: deep gravitational pulse and warm solar flare drone
sun: stack(
  s("bd ~ ~ ~").gain(.8),
  note("c2").s("sawtooth").lpf(sine.range(180, 450).slow(8)).attack(.4).release(1.2).gain(.45)
)

// Inner planets: Mercury (fast), Venus (warm), Earth (steady), Mars (red/syncopated)
inner: n("{7 9 11 14}%8, <2 4>, 0 2 4 2, [~ 1] ~ 3(3,8)")
  .scale("C:lydian").s("triangle").release(.25).room(.4).gain(.32)

// Asteroid belt: tumbling rocky debris between Mars and Jupiter
asteroids: s("hh*16, rim(3,8)").degradeBy(.45).pan(rand).hpf(3500).gain(.25)

// Gas giants: Jupiter (massive) and Saturn (ringed echoes)
gas_giants: n("<[0, 4] [1, 5]>").scale("C:lydian").transpose(-12).s("sawtooth")
  .slow(2).lpf(650).attack(.5).release(1.5).delay(.4).delaytime(3/8).gain(.35)

// Ice giants: Uranus (axial-tilted jux/rev) and Neptune (deep windy blue)
ice_giants: n("<6 4 2 3>").scale("C:lydian").s("sine")
  .slow(4).jux(rev).room(.8).size(.9).attack(.6).release(1.8).gain(.35)

// Kuiper belt: Pluto and distant icy bodies glittering in the outer dark
kuiper: n("7 ~ 11? ~ ~ 14? ~ 9?").scale("C:lydian").transpose(12).s("sine")
  .slow(2).pan(sine.slow(5)).delay(.6).delaytime(1/3).delayfeedback(.55).room(.9).gain(.22)
